Class FPState := mkFP { fp_regs : bvmap 5 word; fp_csr : bv 32 }.
Definition fx0 : FPState := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|500;!2,0!2'1!1,2|21;!1+3!1,2|600;!2'4!1,20,5").

Definition mkst `{fx : FPState} (regs : bvmap 5 word) (pc : word) (mem rom : word -> option byte) : machine_state := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S40!1+3!1,2|600;|30;%~R0!1+8!1+3!1,21!1,;0$fx;R+6$regs;R!2'7!1,2|21;0$pc;R0$mem;R2$rom;R2!8,9#4!1':#5#333!1'<#5#2#1").

Section WithFP1.
Context {fx : FPState}.

