Definition getr (regs : bvmap 5 word) (r : reg) : word :=
  if bv_eqb r 0 then Z_to_bv 64 0 else reg_get regs r.
Definition regupd (regs : bvmap 5 word) (r : reg) (v : word) : bvmap 5 word := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!1,2|21;!1+3!1,2|600;$regs;R!2'701$r;R!1+30$v;R1!5'=01#2#1#3").

