Lemma bv_eqb0_is_x0 : forall r : reg, bv_eqb r 0 = is_x0 r.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$r;R!1+3!1,2|21;!2,>+?!1'@#1").
Qed.

Lemma is_x0_0 : is_x0 0 = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2,>+?,A").
Qed.

Lemma bv_wrap64_mod : forall z : Z, bv_wrap 64 z = (z mod 2^64)%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|10;$z;R+B!2,>+B!2'C#1!2'D!1,E0!1,E|600;").
Qed.

Lemma bv_wrap32_mod : forall z : Z, bv_wrap 32 z = (z mod 2^32)%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|10;$z;R+B!2,>+B!2'C#1!2'D!1,E0!1,E|500;").
Qed.

Lemma bv_eqb_refl : forall {n} (a : bv n), bv_eqb a a = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$n;R+F$a;R!1+3#1vd!1'G!2'H#2#1!3+I+?!3'J#2#1#1,A").
