Lemma rdn_stack : forall segs sp bytes k addr,
  (bv_unsigned sp <= bv_unsigned addr)%Z ->
  (Z.to_nat (bv_unsigned addr - bv_unsigned sp) + k <= length bytes)%nat ->
  (bv_unsigned sp + Z.of_nat (length bytes) < 2^64)%Z ->
